begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.issue_my_vouch_code()','execute'), 'Anonymous issuance denied');
select ok(not has_function_privilege('anon','public.submit_my_education_quiz(uuid,jsonb)','execute'), 'Anonymous grading denied');
select ok(not has_table_privilege('authenticated','public.vouch_codes','insert'), 'Direct code issuance denied');
select ok(not has_table_privilege('authenticated','public.vouch_events','insert'), 'Quota ledger cannot be forged');
select ok(not has_table_privilege('authenticated','public.quiz_attempts','insert'), 'Quiz scores cannot be forged');
select ok(not has_column_privilege('authenticated','public.quiz_options','is_correct','select'), 'Answer keys are not browser-readable');
select ok(not has_column_privilege('authenticated','public.vouch_codes','code_hash','select'), 'Code hashes are not browser-readable');
select throws_ok($$select public.issue_my_vouch_code()$$, 'P0001','Unauthorized','Issuance requires identity');
select throws_ok($$select public.submit_my_education_quiz(gen_random_uuid(),'{}')$$, 'P0001','Unauthorized','Grading requires identity');
insert into auth.users(id,email,raw_user_meta_data) values
 ('98000000-0000-4000-8000-000000000001','trusted-issuer@example.test','{"display_name":"Issuer"}'),
 ('98000000-0000-4000-8000-000000000002','trusted-student@example.test','{"display_name":"Student"}');
set local "request.jwt.claim.role"='service_role';
update public.profiles set is_verified=true where user_id='98000000-0000-4000-8000-000000000001';
set local "request.jwt.claim.role"='authenticated';
insert into public.vouch_user_overrides(user_id,quota) values ('98000000-0000-4000-8000-000000000001',1);
create temporary table test_issued(payload jsonb);
grant select,insert on test_issued to authenticated;
set local role authenticated;
set local "request.jwt.claim.sub"='98000000-0000-4000-8000-000000000002';
select throws_ok($$select public.issue_my_vouch_code()$$,'P0001','Only verified members can vouch.','Unverified issuance denied');
set local "request.jwt.claim.sub"='98000000-0000-4000-8000-000000000001';
insert into test_issued values (public.issue_my_vouch_code());
select is((select length(payload->>'code') from test_issued),20,'One-time code has 80 random bits');
select throws_ok($$select public.issue_my_vouch_code()$$,'P0001','You have used your vouch budget for this period.','Issuance atomically consumes quota');
select throws_ok($$select code_hash from public.vouch_codes$$,'42501',null,'Client cannot bypass code secrecy');
select throws_ok($$select is_correct from public.quiz_options$$,'42501',null,'Client cannot bypass answer-key secrecy');
reset role;
select is((select count(*)::int from public.vouch_events where issuer_id='98000000-0000-4000-8000-000000000001'),1,'Quota failure writes no second event');
select ok((select code like 'HASHED:%' and code_hash=encode(digest((select payload->>'code' from test_issued),'sha256'),'hex') from public.vouch_codes where issuer_id='98000000-0000-4000-8000-000000000001'),'Raw code is absent from storage');
select is((select count(*)::int from public.audit_log where actor_id='98000000-0000-4000-8000-000000000001' and action='vouch.code_issued'),1,'Issuance evidence is atomic');
set local role authenticated;
set local "request.jwt.claim.sub"='98000000-0000-4000-8000-000000000002';
select is((select count(*)::int from public.vouch_codes),0,'Unrelated member cannot enumerate issued codes');
select is(public.redeem_vouch_code((select payload->>'code' from test_issued)), '{"ok":true}'::jsonb,'Hashed code can be redeemed');
select throws_ok($$select public.redeem_vouch_code((select payload->>'code' from test_issued))$$,'P0001','Code is redeemed.','Hashed code stays single-use');
reset role;
-- Legacy service-side insertion also hashes before persistence and remains redeemable.
insert into public.vouch_codes(code,issuer_id,expires_at) values ('LEGACY42','98000000-0000-4000-8000-000000000001',now()+interval '1 day');
select ok((select code like 'HASHED:%' from public.vouch_codes where code_hash=encode(digest('LEGACY42','sha256'),'hex')),'Legacy insert cannot restore plaintext');
insert into public.courses(id,slug,title,status,created_by) values ('98100000-0000-4000-8000-000000000001','trusted-quiz-test','Trusted quiz','published','98000000-0000-4000-8000-000000000001');
insert into public.course_modules(id,course_id,title) values ('98200000-0000-4000-8000-000000000001','98100000-0000-4000-8000-000000000001','Module');
insert into public.lessons(id,module_id,slug,title,status) values ('98300000-0000-4000-8000-000000000001','98200000-0000-4000-8000-000000000001','lesson','Lesson','published');
insert into public.quizzes(id,lesson_id,title) values ('98400000-0000-4000-8000-000000000001','98300000-0000-4000-8000-000000000001','Quiz');
insert into public.quiz_questions(id,quiz_id,prompt) values ('98500000-0000-4000-8000-000000000001','98400000-0000-4000-8000-000000000001','Question');
insert into public.quiz_options(id,question_id,label,is_correct) values
 ('98600000-0000-4000-8000-000000000001','98500000-0000-4000-8000-000000000001','Correct',true),
 ('98600000-0000-4000-8000-000000000002','98500000-0000-4000-8000-000000000001','Incorrect',false);
set local role authenticated;
set local "request.jwt.claim.sub"='98000000-0000-4000-8000-000000000002';
select is(public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{}')->>'score','0','Unanswered question grades zero');
select is(public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{"98500000-0000-4000-8000-000000000001":"98600000-0000-4000-8000-000000000002"}')->>'passed','false','Wrong answer cannot claim pass');
select is(public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{"98500000-0000-4000-8000-000000000001":"98600000-0000-4000-8000-000000000001"}')->>'score','100','Server grades a valid correct answer');
select throws_ok($$select public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{"00000000-0000-4000-8000-000000000001":"98600000-0000-4000-8000-000000000001"}')$$,'P0001','Answers must belong to this quiz and question','Foreign question rejected');
select throws_ok($$select public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{"98500000-0000-4000-8000-000000000001":true}')$$,'P0001','Answers must belong to this quiz and question','Malformed answer rejected');
select throws_ok($$select public.get_managed_education_quiz('98300000-0000-4000-8000-000000000001')$$,'42501','Education author authority is required','Ordinary member cannot obtain editor answers');
select throws_ok($$insert into public.quiz_attempts(user_id,quiz_id,score,passed) values ('98000000-0000-4000-8000-000000000002','98400000-0000-4000-8000-000000000001',100,true)$$,'42501',null,'Direct score forgery denied');
reset role;
select is((select count(*)::int from public.quiz_attempts where user_id='98000000-0000-4000-8000-000000000002' and quiz_id='98400000-0000-4000-8000-000000000001'),3,'Invalid attempts persist no scores');
update public.lessons set status='draft' where id='98300000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.submit_my_education_quiz('98400000-0000-4000-8000-000000000001','{}')$$,'P0001','Quiz is not available','Unpublished lesson cannot be graded');
reset role;
insert into public.user_roles(user_id,role) values ('98000000-0000-4000-8000-000000000001','editor');
set local role authenticated;
set local "request.jwt.claim.sub"='98000000-0000-4000-8000-000000000001';
select is(public.get_managed_education_quiz('98300000-0000-4000-8000-000000000001') #>> '{questions,0,options,0,is_correct}','true','Authorized editor uses the protected answer projection');
reset role;
insert into public.member_suspensions(user_id,actor_id,reason) values ('98000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000002','Test suspension');
set local role authenticated;
select throws_ok($$select public.issue_my_vouch_code()$$,'P0001','Your account is suspended.','Suspension blocks issuance before quota');
select throws_ok($$select public.get_managed_education_quiz('98300000-0000-4000-8000-000000000001')$$,'42501','Education author authority is required','Suspended author loses answer projection');
select * from finish();
rollback;
